import React from 'react';

const TestAddRisk = () => {
  return (
    <div style={{
      padding: '2rem',
      backgroundColor: '#ecfdf5',
      border: '2px solid #10b981',
      borderRadius: '0.5rem',
      margin: '2rem',
      textAlign: 'center'
    }}>
      <h1 style={{ color: '#059669' }}>
        ✅ Test Add Risk Page - WORKING!
      </h1>
      <p style={{ color: '#047857' }}>
        If you can see this green box, React components are loading correctly!
      </p>
      <div style={{
        backgroundColor: '#f0fdf4',
        padding: '1rem',
        borderRadius: '0.25rem',
        border: '1px solid #bbf7d0',
        marginTop: '1rem'
      }}>
        <h3>Magic Risk Articulation Test</h3>
        <textarea
          placeholder="Risk context here..."
          rows={3}
          style={{
            width: '100%',
            padding: '0.5rem',
            border: '1px solid #d1d5db',
            borderRadius: '0.25rem',
            marginBottom: '0.5rem'
          }}
        />
        <button style={{
          padding: '0.5rem 1rem',
          backgroundColor: '#8b5cf6',
          color: 'white',
          border: 'none',
          borderRadius: '0.25rem',
          cursor: 'pointer'
        }}>
          ✨ Articulate Risk
        </button>
      </div>
    </div>
  );
};

export default TestAddRisk;
